CREATE OR REPLACE FUNCTION public.apply_voucher_to_order(p_order_id integer, p_voucher_code character varying)
 RETURNS numeric
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    voucher_record RECORD;
    order_record RECORD;
    v_discount_amount DECIMAL(18,2) := 0;
    final_total DECIMAL(18,2);
BEGIN
    -- Get order details
    SELECT * INTO order_record FROM "order" WHERE order_id = p_order_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Order not found';
    END IF;

    -- Get voucher details
    SELECT * INTO voucher_record FROM voucher WHERE code = p_voucher_code;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Voucher not found';
    END IF;

    -- Validate voucher
    IF NOT voucher_record.is_active THEN
        RAISE EXCEPTION 'Voucher is not active';
    END IF;

    IF voucher_record.valid_to < CURRENT_TIMESTAMP THEN
        RAISE EXCEPTION 'Voucher has expired';
    END IF;

    -- Check if voucher already applied to this order
    IF order_record.voucher_id IS NOT NULL THEN
        RAISE EXCEPTION 'Order already has a voucher applied';
    END IF;

    -- Calculate discount
    v_discount_amount := calculate_order_total(order_record.total_amount, voucher_record.voucher_id, order_record.shipping_fee)
                     - order_record.total_amount + order_record.discount_amount;

    -- Update order with voucher
    UPDATE "order"
    SET voucher_id = voucher_record.voucher_id,
        discount_amount = v_discount_amount,
        final_amount = total_amount - v_discount_amount + shipping_fee,
        updated_at = CURRENT_TIMESTAMP
    WHERE order_id = p_order_id;

    -- Update voucher usage
    UPDATE voucher
    SET usage_count = usage_count + 1
    WHERE voucher_id = voucher_record.voucher_id;

    -- Log the voucher application
    PERFORM log_system_action(
        order_record.buyer_id,
        'VOUCHER_APPLIED',
        'order',
        p_order_id,
        'Applied voucher ' || p_voucher_code || ' with discount ' || v_discount_amount
    );

    RETURN v_discount_amount;
END;
$function$

CREATE OR REPLACE FUNCTION public.authenticate_user(p_username_or_email text, p_password text)
 RETURNS TABLE(user_id integer, username character varying, email character varying, full_name character varying, is_active boolean, role_name character varying)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    user_record RECORD;
    login_successful BOOLEAN := FALSE;
BEGIN
    -- Find user by username or email
    SELECT u.*, r.role_name INTO user_record
    FROM users_full u
    JOIN user_role ur ON u.user_id = ur.user_id
    JOIN role r ON ur.role_id = r.role_id
    WHERE (u.username = p_username_or_email OR u.email = p_username_or_email)
    AND u.is_deleted = FALSE;

    -- Check if user exists
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Invalid username or password';
    END IF;

    -- Check if user is active
    IF NOT user_record.is_active THEN
        RAISE EXCEPTION 'Account is deactivated';
    END IF;

    -- Verify password
    IF verify_password(p_password, user_record.password_hash) THEN
        login_successful := TRUE;

        -- Update last login
        UPDATE user_core SET last_login = CURRENT_TIMESTAMP WHERE user_core.user_id = user_record.user_id;

        -- Log successful login
        PERFORM log_system_action(user_record.user_id, 'LOGIN_SUCCESS', 'user', user_record.user_id, 'Successful login');
    ELSE
        -- Log failed login attempt
        PERFORM log_system_action(user_record.user_id, 'LOGIN_FAILED', 'user', user_record.user_id, 'Failed login attempt');

        RAISE EXCEPTION 'Invalid username or password';
    END IF;

    -- Return user data
    RETURN QUERY
    SELECT
        user_record.user_id,
        user_record.username,
        user_record.email,
        user_record.full_name,
        user_record.is_active,
        user_record.role_name;
END;
$function$

CREATE OR REPLACE FUNCTION public.calculate_order_total(p_subtotal numeric, p_voucher_id integer DEFAULT NULL::integer, p_shipping_fee numeric DEFAULT 0)
 RETURNS numeric
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    discount_amount DECIMAL(18,2) := 0;
    voucher_record RECORD;
    final_total DECIMAL(18,2);
BEGIN
    -- Validate inputs
    IF p_subtotal < 0 THEN
        RAISE EXCEPTION 'Subtotal cannot be negative';
    END IF;

    IF p_shipping_fee < 0 THEN
        RAISE EXCEPTION 'Shipping fee cannot be negative';
    END IF;

    -- Get voucher details if provided
    IF p_voucher_id IS NOT NULL THEN
        SELECT * INTO voucher_record
        FROM voucher
        WHERE voucher_id = p_voucher_id
        AND is_active = TRUE
        AND valid_to > CURRENT_TIMESTAMP;

        IF NOT FOUND THEN
            RAISE EXCEPTION 'Invalid or expired voucher';
        END IF;

        -- Check usage limit
        IF voucher_record.max_usage IS NOT NULL AND voucher_record.usage_count >= voucher_record.max_usage THEN
            RAISE EXCEPTION 'Voucher usage limit exceeded';
        END IF;

        -- Check minimum order value
        IF p_subtotal < voucher_record.min_order_amount THEN
            RAISE EXCEPTION 'Order value does not meet voucher minimum requirement of %', voucher_record.min_order_amount;
        END IF;

        -- Calculate discount
        IF voucher_record.discount_type = 1 THEN
            -- Percentage discount
            discount_amount := p_subtotal * voucher_record.discount_value / 100;
        ELSE
            -- Fixed amount discount
            discount_amount := voucher_record.discount_value;
        END IF;

        -- Ensure discount doesn't exceed subtotal
        discount_amount := LEAST(discount_amount, p_subtotal);
    END IF;

    -- Calculate final total
    final_total := GREATEST(p_subtotal - discount_amount + p_shipping_fee, 0);

    RETURN final_total;
END;
$function$

CREATE OR REPLACE FUNCTION public.calculate_percentage(part numeric, total numeric)
 RETURNS numeric
 LANGUAGE plpgsql
 IMMUTABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
    IF total = 0 THEN
        RETURN 0;
    END IF;
    RETURN ROUND((part / total * 100)::DECIMAL(5,2), 2);
END;
$function$

CREATE OR REPLACE FUNCTION public.check_no_self_buying()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    order_buyer_id INT;
    product_seller_id INT;
BEGIN
    SELECT buyer_id INTO order_buyer_id
    FROM "order"
    WHERE order_id = NEW.order_id;

    SELECT seller_id INTO product_seller_id
    FROM product
    WHERE product_id = NEW.product_id;

    IF order_buyer_id IS NULL OR product_seller_id IS NULL THEN
        RAISE EXCEPTION 'INVALID_ORDER_OR_PRODUCT: Invalid order or product reference';
    END IF;

    IF order_buyer_id = product_seller_id THEN
        PERFORM log_system_action(
            order_buyer_id,
            'SELF_BUY_BLOCKED',
            'order_detail',
            NEW.order_detail_id,
            'Attempted to buy own product (product_id: ' || NEW.product_id || ')'
        );
        RAISE EXCEPTION 'BUSINESS_RULE_VIOLATION: Sellers cannot buy their own products.';
    END IF;

    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.create_user_with_hash(p_username character varying, p_email character varying, p_password text, p_full_name character varying, p_phone_number character varying DEFAULT NULL::character varying, p_address character varying DEFAULT NULL::character varying)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    new_user_id INTEGER;
    email_regex TEXT := '^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}$';
BEGIN
    -- Validate inputs
    IF p_username IS NULL OR length(trim(p_username)) = 0 THEN
        RAISE EXCEPTION 'Username cannot be empty';
    END IF;

    IF p_email IS NULL OR length(trim(p_email)) = 0 THEN
        RAISE EXCEPTION 'Email cannot be empty';
    END IF;

    IF p_full_name IS NULL OR length(trim(p_full_name)) = 0 THEN
        RAISE EXCEPTION 'Full name cannot be empty';
    END IF;

    -- Validate email format
    IF NOT (p_email ~ email_regex) THEN
        RAISE EXCEPTION 'Invalid email format';
    END IF;

    -- Check for existing username
    IF EXISTS (SELECT 1 FROM user_core WHERE username = trim(p_username) AND is_deleted = FALSE) THEN
        RAISE EXCEPTION 'Username already exists';
    END IF;

    -- Check for existing email
    IF EXISTS (SELECT 1 FROM user_core WHERE email = trim(p_email) AND is_deleted = FALSE) THEN
        RAISE EXCEPTION 'Email already exists';
    END IF;

    INSERT INTO user_core(username,email,email_verified)
    VALUES(trim(p_username),trim(p_email),FALSE) RETURNING user_id INTO new_user_id;
    INSERT INTO user_profile(user_id,full_name,phone_number,address)
    VALUES(new_user_id,trim(p_full_name),NULLIF(trim(p_phone_number),''),NULLIF(trim(p_address),''));
    INSERT INTO user_secret(user_id,password_hash,random_key)
    VALUES(new_user_id,hash_password(p_password),generate_random_key());
    INSERT INTO user_wallet(user_id) VALUES(new_user_id);

    -- Log user creation
    PERFORM log_system_action(new_user_id, 'USER_CREATED', 'user', new_user_id, 'User account created');

    RETURN new_user_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.enforce_image_site()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE remainder smallint;
BEGIN
    SELECT id_remainder INTO STRICT remainder FROM public.site_config WHERE singleton;
    IF NEW.image_id <= 0 OR mod(NEW.image_id, 2) <> remainder THEN
        RAISE EXCEPTION 'image_wrong_id_allocation' USING ERRCODE = '23514';
    END IF;
    IF TG_OP = 'UPDATE' AND (NEW.image_id, NEW.product_id) IS DISTINCT FROM (OLD.image_id, OLD.product_id) THEN
        RAISE EXCEPTION 'image_ownership_immutable' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.enforce_product_site()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE config public.site_config%ROWTYPE;
BEGIN
    SELECT * INTO STRICT config FROM public.site_config WHERE singleton;
    IF NEW.site_id <> config.site_id THEN
        RAISE EXCEPTION 'product_wrong_site' USING ERRCODE = '23514';
    END IF;
    IF NEW.product_id <= 0 OR mod(NEW.product_id, 2) <> config.id_remainder THEN
        RAISE EXCEPTION 'product_wrong_id_allocation' USING ERRCODE = '23514';
    END IF;
    IF TG_OP = 'UPDATE' AND (NEW.product_id, NEW.seller_id, NEW.site_id)
        IS DISTINCT FROM (OLD.product_id, OLD.seller_id, OLD.site_id) THEN
        RAISE EXCEPTION 'product_ownership_immutable' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.etl_capture_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
 table_name text := TG_ARGV[0]; id_column text := TG_ARGV[1];
 before_row jsonb; after_row jsonb; source_key jsonb; old_key jsonb; new_key jsonb;
 fields text[] := '{}'; field text; zone text; targets jsonb := '[]';
 candidate jsonb; target jsonb; related record; source_id bigint;
BEGIN
 IF TG_OP<>'INSERT' THEN before_row:=to_jsonb(OLD); END IF;
 IF TG_OP<>'DELETE' THEN after_row:=to_jsonb(NEW); END IF;
 old_key:=jsonb_build_object(id_column,before_row->id_column);
 new_key:=jsonb_build_object(id_column,after_row->id_column);
 IF table_name='system_log' THEN
  old_key:=old_key||jsonb_build_object('created_at',before_row->'created_at');
  new_key:=new_key||jsonb_build_object('created_at',after_row->'created_at');
 END IF;
 fields:=CASE table_name WHEN 'product' THEN ARRAY['created_at','updated_at']
  WHEN 'order' THEN ARRAY['order_date'] WHEN 'review' THEN ARRAY['created_at','updated_at']
  WHEN 'system_log' THEN ARRAY['created_at'] WHEN 'violation_log' THEN ARRAY['created_at']
  WHEN 'system_feedback' THEN ARRAY['created_at'] ELSE '{}'::text[] END;
 IF TG_OP<>'DELETE' THEN
  FOREACH field IN ARRAY fields LOOP
   IF after_row->>field IS NULL THEN CONTINUE; END IF;
   zone:=NULL;
   IF TG_OP='UPDATE' AND after_row->>field IS NOT DISTINCT FROM before_row->>field THEN
    SELECT source_zone INTO zone FROM etl_time_origin
     WHERE source_table=table_name AND etl_time_origin.source_key=old_key AND field_name=field
      AND source_value=(before_row->>field)::timestamp;
   END IF;
   -- An unchanged legacy value without provenance is deliberately not guessed.
   IF zone IS NULL AND TG_OP='UPDATE' AND after_row->>field IS NOT DISTINCT FROM before_row->>field THEN
    CONTINUE;
   END IF;
   INSERT INTO etl_time_origin(source_table,source_key,field_name,source_value,source_zone)
    VALUES(table_name,new_key,field,(after_row->>field)::timestamp,COALESCE(zone,current_setting('TimeZone')))
    ON CONFLICT ON CONSTRAINT etl_time_origin_pkey DO UPDATE SET
     source_value=excluded.source_value,source_zone=excluded.source_zone,recorded_at=clock_timestamp();
  END LOOP;
 END IF;
 FOR candidate IN SELECT value FROM jsonb_array_elements(jsonb_build_array(before_row,after_row))
  WHERE value<>'null'::jsonb LOOP
  source_id:=(candidate->>id_column)::bigint;
  IF table_name IN ('product','order','review','violation_log','system_feedback','system_log') THEN
   target:=jsonb_build_object('id',source_id);
   IF table_name='system_log' THEN target:=target||jsonb_build_object('created_at',candidate->'created_at'); END IF;
   targets:=targets||jsonb_build_array(jsonb_build_object('entity',CASE table_name
    WHEN 'system_feedback' THEN 'contact' ELSE table_name END,'key',target));
  ELSIF table_name='product_image' THEN
   targets:=targets||jsonb_build_array(jsonb_build_object('entity','product','key',jsonb_build_object('id',candidate->'product_id')));
  ELSIF table_name IN ('order_detail','transaction') THEN
   targets:=targets||jsonb_build_array(jsonb_build_object('entity','order','key',jsonb_build_object('id',candidate->'order_id')));
  END IF;
  -- Rebuild snapshots whose CURRENT dimensions/voucher metadata changed, not historical prices.
  IF table_name='product' THEN
   FOR related IN SELECT DISTINCT order_id FROM order_detail WHERE product_id=source_id LOOP
    targets:=targets||jsonb_build_array(jsonb_build_object('entity','order','key',jsonb_build_object('id',related.order_id)));
   END LOOP;
  ELSIF table_name='voucher' THEN
   FOR related IN SELECT order_id FROM "order" WHERE voucher_id=source_id LOOP
    targets:=targets||jsonb_build_array(jsonb_build_object('entity','order','key',jsonb_build_object('id',related.order_id)));
   END LOOP;
  END IF;
 END LOOP;
 source_key:=CASE WHEN TG_OP='DELETE' THEN old_key ELSE new_key END;
 FOR target IN SELECT DISTINCT value FROM jsonb_array_elements(targets) LOOP
  INSERT INTO etl_outbox(source_table,source_key,entity_type,entity_key,operation)
   VALUES(table_name,source_key,target->>'entity',target->'key',TG_OP);
 END LOOP;
 RETURN COALESCE(NEW,OLD);
END $function$

CREATE OR REPLACE FUNCTION public.generate_password_reset_token()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    token TEXT;
BEGIN
    -- Generate 32 bytes of random data, base64url encoded
    token := encode(gen_random_bytes(32), 'base64');
    -- Make URL-safe by replacing problematic characters
    token := replace(replace(token, '+', '-'), '/', '_');
    -- Remove padding
    token := rtrim(token, '=');

    RETURN token;
END;
$function$

CREATE OR REPLACE FUNCTION public.generate_transaction_code()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    timestamp_part TEXT;
    random_part TEXT;
BEGIN
    -- Get timestamp part
    timestamp_part := TO_CHAR(CURRENT_TIMESTAMP, 'YYYYMMDD_HH24MISS');

    -- Generate 4 random digits
    random_part := LPAD(FLOOR(RANDOM() * 10000)::TEXT, 4, '0');

    RETURN 'TXN_' || timestamp_part || '_' || random_part;
END;
$function$

CREATE OR REPLACE FUNCTION public.generic_audit_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    action_type VARCHAR(10);
    record_id INT;
    change_description TEXT;
BEGIN
    -- Determine action type
    IF TG_OP = 'INSERT' THEN
        action_type := 'INSERT';
        record_id := NEW.id;
        change_description := 'Record created';
    ELSIF TG_OP = 'UPDATE' THEN
        action_type := 'UPDATE';
        record_id := NEW.id;
        change_description := 'Record updated';
    ELSIF TG_OP = 'DELETE' THEN
        action_type := 'DELETE';
        record_id := OLD.id;
        change_description := 'Record deleted';
    ELSE
        RETURN COALESCE(NEW, OLD);
    END IF;

    -- Log the change (user_id will be NULL for system/auto operations)
    PERFORM log_system_action(NULL, action_type, TG_TABLE_NAME, record_id, change_description);

    RETURN COALESCE(NEW, OLD);
END;
$function$

CREATE OR REPLACE FUNCTION public.hash_password(password text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    hashed_password TEXT;
BEGIN
    -- Validate input
    IF password IS NULL OR length(trim(password)) = 0 THEN
        RAISE EXCEPTION 'Password cannot be empty';
    END IF;

    IF length(password) < 6 THEN
        RAISE EXCEPTION 'Password must be at least 6 characters long';
    END IF;

    -- Hash the password
    hashed_password := crypt(password, gen_salt('bf', 8));

    RETURN hashed_password;
END;
$function$

CREATE OR REPLACE FUNCTION public.log_user_login(p_user_id integer, p_ip_address inet DEFAULT NULL::inet, p_user_agent text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    login_description TEXT;
BEGIN
    -- Update last login timestamp
    UPDATE user_core
    SET last_login = CURRENT_TIMESTAMP
    WHERE user_id = p_user_id AND is_deleted = FALSE;

    -- Build login description
    login_description := 'User login';
    IF p_ip_address IS NOT NULL THEN
        login_description := login_description || ' from IP: ' || p_ip_address::TEXT;
    END IF;
    IF p_user_agent IS NOT NULL THEN
        login_description := login_description || ' using: ' || substring(p_user_agent, 1, 100);
    END IF;

    -- Log the login event
    PERFORM log_system_action(p_user_id, 'LOGIN', 'user', p_user_id, login_description);
END;
$function$

CREATE OR REPLACE FUNCTION public.queue_unlinked_media()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE old_url text;
BEGIN
 IF TG_TABLE_NAME='product_image' THEN
  old_url:=OLD.image_url;
  IF TG_OP='UPDATE' AND NEW.image_url IS NOT DISTINCT FROM OLD.image_url THEN RETURN NEW; END IF;
 ELSE
  old_url:=OLD.avatar_url;
  IF NEW.avatar_url IS NOT DISTINCT FROM OLD.avatar_url THEN RETURN NEW; END IF;
  -- Seed/shared avatars are retained. Only immutable user uploads are collected automatically.
  IF old_url !~ '^/media/users/[0-9]+/avatar-[0-9a-f]{32}\.[a-z]+$' THEN RETURN NEW; END IF;
 END IF;
 IF old_url LIKE '/media/%' THEN
  INSERT INTO media_deletions(url_path) VALUES(old_url)
   ON CONFLICT(url_path) DO UPDATE SET status='pending',available_at=clock_timestamp(),
     processed_at=NULL,last_error_code=NULL;
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.verify_password(password text, hashed_password text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    is_valid BOOLEAN := FALSE;
BEGIN
    -- Validate inputs
    IF password IS NULL OR hashed_password IS NULL THEN
        RETURN FALSE;
    END IF;

    -- Verify password
    IF crypt(password, hashed_password) = hashed_password THEN
        is_valid := TRUE;
    END IF;

    RETURN is_valid;
END;
$function$
